steps.action:
curl -s https://api.linear.app/graphql \
  -X POST \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      teams {
        nodes {
          id
          name
          issues(filter: {
            project: { name: { eq: \"Website Redesign\" } },
            workflowState: { name: { eq: \"Done\" } },
            completedAt: { gte: \"2024-08-14T00:00:00.000Z\" },
            completedAt: { lte: \"2024-08-14T23:59:59.999Z\" }
          }) {
            nodes {
              id
              identifier
              title
              description
              priority
              workflowState {
                name
              }
              completedAt
              project {
                name
              }
            }
          }
        }
      }
    }"
  }'
